        WHERE "Rating" > 200;
    ELSIF flag = 3 AND temp_text = 'OVER_LIMIT' THEN
        DELETE FROM "Restaurant"
        WHERE "Rating" > 150;
    ELSIF flag = 4 AND temp_num > 5 THEN
        UPDATE "Student"
        SET "Sex" = 'PROCESSED'
        WHERE "Major" < arg1;
    ELSE
        UPDATE "Restaurant_Type"
        SET "ResTypeName" = 'DEFAULT'
        WHERE "ResTypeID" IS NULL;
    END IF;
END sp;
